#nullable enable // autogenerated

using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.axolotlSuit)]
    public class AxolotlSuit : AIEntityBehaviour
    {
        public AxolotlSuit(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(LogicEnemyProps.HARMLESS, BooleanOperator.Or, PROP_EMPTY));
            AddModifier(new BooleanModifier(LogicEnemyProps.NOT_ACTIVE_ENEMY, BooleanOperator.Or, PROP_EMPTY));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            if (!entity.IsPreviewEnemy() && !IsEmpty(entity))
            {
                entity.PlaySound(VanillaSoundID.axolotlSuitAppear);
            }
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            switch (entity.State)
            {
                case STATE_ENTERED:
                    UpdateBeingEnteredState(entity);
                    break;
            }
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (!entity.WillRemoveOnDeath(info))
            {
                Explosion.Spawn(entity, entity.GetCenter(), entity.GetScaledSize());
                entity.Remove();
            }
        }
        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            if (entity.IsAboveLand())
            {
                entity.Level.ShakeScreen(3, 0, 10);
                entity.PlaySound(VanillaSoundID.axolotlSuitSmash);
            }
        }
        private void UpdateBeingEnteredState(Entity entity)
        {
            var stateTimer = GetStateTimer(entity);
            if (stateTimer == null)
            {
                stateTimer = TimerHelper.NewSecondTimer(ENTER_SECONDS);
                SetStateTimer(entity, stateTimer);
            }
            if (stateTimer.RunToExpired())
            {
                SetBeingEntered(entity, false);
            }
        }
        public static void SetStateTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_STATE_TIMER, timer);
        public static FrameTimer? GetStateTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_STATE_TIMER);
        public static void SetPilotHPPercent(Entity entity, float value) => entity.SetBehaviourField(PROP_PILOT_HP_PERCENT, value);
        public static float GetPilotHPPercent(Entity entity) => entity.GetBehaviourField<float>(PROP_PILOT_HP_PERCENT);
        public static void SetEmpty(Entity entity, bool value) => entity.SetBehaviourField(PROP_EMPTY, value);
        public static bool IsEmpty(Entity entity) => entity.GetBehaviourField<bool>(PROP_EMPTY);
        public static void SetBeingEntered(Entity entity, bool value) => entity.SetBehaviourField(PROP_BEING_ENTERED, value);
        public static bool IsBeingEntered(Entity entity) => entity.GetBehaviourField<bool>(PROP_BEING_ENTERED);

        public const int STATE_ENTERED = VanillaEnemyStates.AXOLOTL_SUIT_BEING_ENTERED;
        public const float ENTER_SECONDS = 0.5f;
        public static readonly VanillaEntityPropertyMeta<bool> PROP_EMPTY = new VanillaEntityPropertyMeta<bool>("empty");
        public static readonly VanillaEntityPropertyMeta<bool> PROP_BEING_ENTERED = new VanillaEntityPropertyMeta<bool>("being_entered");
        public static readonly VanillaEntityPropertyMeta<float> PROP_PILOT_HP_PERCENT = new VanillaEntityPropertyMeta<float>("pilot_hp_percent", 1f);
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("state_timer");
    }
}
